<fieldset class="question-editor"><legend>Question</legend><div class="form-grid"><label class="field full">Intitulé<textarea name="questions[<?= $e($index) ?>][text]" maxlength="2000" required><?= $e($question['text']) ?></textarea></label><label class="field full">Choix de réponse — un choix par ligne<textarea name="questions[<?= $e($index) ?>][choices]" maxlength="10000" required><?= $e(implode("\n",$question['choices'])) ?></textarea></label><label class="field">Numéros des bonnes réponses, séparés par des virgules<input name="questions[<?= $e($index) ?>][correct]" value="<?= $e(implode(',',array_map(static fn(int $answer): int => $answer+1,$question['correct']))) ?>" required></label><label class="field">Points<input class="question-points" name="questions[<?= $e($index) ?>][points]" type="number" min="1" max="30" value="<?= $e($question['points']) ?>" required></label></div><button class="button secondary small remove-question" type="button">Supprimer cette question</button></fieldset>
